const u = $json;
const cb = u.callback_query;
const msg = u.message || cb?.message || {};
const from = cb?.from || msg.from || {};
const text = msg.text || '';
const data = cb?.data || '';
return [{json:{
  telegram_id:String(from.id || ''),
  chat_id:String(msg.chat?.id || from.id || ''),
  nombre:[from.first_name,from.last_name].filter(Boolean).join(' '),
  username:from.username || '',
  tipo: cb ? 'callback' : 'message',
  texto:text,
  callback_data:data,
  callback_query_id:cb?.id || '',
  accion: cb ? data : (text.startsWith('/') ? text.split(' ')[0] : 'texto')
}}];

const evt = $('Normalizar Evento').first().json;
const menu = $('Leer MENU').all()
  .map(i => i.json)
  .filter(x => x.id_producto && String(x.activo || 'SI').toUpperCase() !== 'NO');

const sessions = $('Leer SESSIONS').all()
  .map(i => i.json)
  .filter(x => x.telegram_id);

const users = $('Leer USUARIOS').all()
  .map(i => i.json)
  .filter(x => x.telegram_id);

const sess = sessions.find(s => String(s.telegram_id) === evt.telegram_id) || {
  telegram_id: evt.telegram_id,
  pantalla_actual: 'INICIO',
  carrito_temporal: '[]',
  categoria_actual: ''
};

let cart = [];
try {
  cart = JSON.parse(sess.carrito_temporal || '[]');
} catch (e) {
  cart = [];
}

const money = n => new Intl.NumberFormat('es-CO', {
  style: 'currency',
  currency: 'COP',
  maximumFractionDigits: 0
}).format(Number(n || 0));

const total = () => cart.reduce(
  (acc, x) => acc + Number(x.precio) * Number(x.cantidad),
  0
);

let response = {
  chat_id: evt.chat_id,
  text: '',
  keyboard: [],
  ui_type: 'SINGLE',
  session: { ...sess },
  order: null,
  stock_updates: [],
  register_user: null
};

if (!users.find(u => String(u.telegram_id) === evt.telegram_id)) {
  response.register_user = {
    telegram_id: evt.telegram_id,
    nombre_completo: evt.nombre,
    departamento_oficina: 'POR DEFINIR',
    puntos_lealtad: 0,
    activo: 'SI',
    fecha_registro: new Date().toLocaleDateString('en-CA', {timeZone:'America/Bogota'})
  };
}

const categoryButtons = ['Bebidas', 'Comidas', 'Snacks']
  .map(c => [{ text: c, callback_data: 'CAT:' + c }]);

const home = () => {
  response.text =
    `☕ *DeliveryBot Cafetería*\n` +
    `Hola ${evt.nombre || '👋'}.\n\n` +
    `¿Qué deseas hacer?`;

  response.keyboard = [
    [{ text: '🛒 Realizar pedido', callback_data: 'MENU' }],
    [{ text: '📋 Consultar menú', callback_data: 'VIEW_MENU' }],
    [
      { text: '🧺 Ver carrito', callback_data: 'CART' },
      { text: '📦 Estado', callback_data: 'STATUS' }
    ],
    [{ text: '📜 Historial', callback_data: 'HISTORY' }],
    [{ text: '🏆 4. Ver mis Puntos', callback_data: 'POINTS' }]
  ];

  response.ui_type = 'HOME';
  response.session.pantalla_actual = 'INICIO';
};

const action = evt.callback_data || evt.accion;

if (['/start', 'HOME'].includes(action)) {

  home();

} else if (action === 'VIEW_MENU') {

  const categorias = ['Bebidas', 'Comidas', 'Snacks'];
  const bloques = categorias.map(cat => {
    const items = menu.filter(x => x.categoria === cat);
    if (!items.length) return '';
    const lineas = items.map(x =>
      `• ${x.nombre} — ${money(x.precio)}${Number(x.stock) <= 0 ? ' (Agotado)' : ''}`
    ).join('\n');
    return `*${cat}*\n${lineas}`;
  }).filter(Boolean);

  response.text =
    `📋 *Menú de la cafetería*\n\n` +
    bloques.join('\n\n') +
    `\n\n_Modo consulta: aquí puedes ver productos y precios sin realizar una compra._`;

  response.keyboard = [[
    { text: '🏠 Menú principal', callback_data: 'HOME' }
  ]];

  response.ui_type = 'SINGLE';
  response.session.pantalla_actual = 'CONSULTA_MENU';

} else if (['/menu', 'MENU'].includes(action)) {

  response.text = 'Selecciona una categoría:';
  response.keyboard = categoryButtons;
  response.ui_type = 'CATEGORIES';
  response.session.pantalla_actual = 'CATEGORIAS';

} else if (action.startsWith('CAT:')) {

  const cat = action.slice(4);
  const items = menu.filter(
    x => x.categoria === cat && Number(x.stock) > 0
  );

  if (!items.length) {
    response.text = `⚠️ En este momento no hay productos disponibles en *${cat}*.`;
    response.keyboard = [[
      { text: '⬅️ Categorías', callback_data: 'MENU' }
    ]];
    response.ui_type = 'SINGLE';
  } else {
    // V3 usa hasta 3 botones de producto por categoría.
    // Los datos actuales de prueba tienen exactamente 3 por categoría.
    const visible = items.slice(0, 3);

    response.text = `*${cat}*\nSelecciona un producto:`;
    response.keyboard = visible.map(x => [{
      text: `${x.nombre} · ${money(x.precio)} · stock ${x.stock}`,
      callback_data: `PROD:${x.id_producto}`
    }]);

    // Completa siempre 3 slots para que el nodo Telegram V3 tenga estructura estable.
    while (response.keyboard.length < 3) {
      response.keyboard.push([{
        text: 'No disponible',
        callback_data: 'MENU'
      }]);
    }

    response.keyboard.push([{
      text: '⬅️ Categorías',
      callback_data: 'MENU'
    }]);

    response.ui_type = 'PRODUCTS';
    response.session.pantalla_actual = 'PRODUCTOS';
    response.session.categoria_actual = cat;
  }

} else if (action.startsWith('PROD:')) {

  const id = action.slice(5);
  const p = menu.find(x => String(x.id_producto) === id);

  if (!p || Number(p.stock) <= 0) {
    response.text = '⚠️ Producto no disponible.';
    response.keyboard = [[
      { text: '⬅️ Menú', callback_data: 'MENU' }
    ]];
    response.ui_type = 'SINGLE';
  } else {
    response.text =
      `*${p.nombre}*\n` +
      `${p.descripcion || ''}\n` +
      `Precio: *${money(p.precio)}*\n` +
      `Stock: ${p.stock}\n\n` +
      `¿Cuántas unidades deseas?`;

    response.keyboard = [
      [1, 2, 3].map(q => ({
        text: String(q),
        callback_data: `ADD:${id}:${q}`
      })),
      [{
        text: '⬅️ Volver',
        callback_data: `CAT:${p.categoria}`
      }]
    ];

    response.ui_type = 'QUANTITY';
    response.session.pantalla_actual = 'CANTIDAD';
  }

} else if (action.startsWith('ADD:')) {

  const [, id, qraw] = action.split(':');
  const q = Number(qraw || 1);
  const p = menu.find(x => String(x.id_producto) === id);

  if (!p || Number(p.stock) < q) {
    response.text = '⚠️ No hay stock suficiente para esa cantidad.';
    response.keyboard = [[
      { text: '⬅️ Menú', callback_data: 'MENU' }
    ]];
    response.ui_type = 'SINGLE';
  } else {
    const existing = cart.find(x => x.id === id);

    if (existing) {
      const newQty = Number(existing.cantidad) + q;
      if (newQty > Number(p.stock)) {
        response.text = `⚠️ Ya tienes ${existing.cantidad} unidad(es) de ${p.nombre}. No hay stock para agregar ${q} más.`;
        response.keyboard = [[
          { text: '🧺 Ver carrito', callback_data: 'CART' }
        ]];
        response.ui_type = 'SINGLE';
      } else {
        existing.cantidad = newQty;
        response.text = `✅ ${q} × ${p.nombre} agregado(s).\n\nSubtotal: *${money(total())}*`;
        response.keyboard = [
          [{ text: '➕ Seguir comprando', callback_data: 'MENU' }],
          [{ text: '🧺 Ver carrito', callback_data: 'CART' }]
        ];
        response.ui_type = 'ADDED';
        response.session.pantalla_actual = 'CARRITO';
      }
    } else {
      cart.push({
        id,
        nombre: p.nombre,
        cantidad: q,
        precio: Number(p.precio)
      });

      response.text = `✅ ${q} × ${p.nombre} agregado(s).\n\nSubtotal: *${money(total())}*`;
      response.keyboard = [
        [{ text: '➕ Seguir comprando', callback_data: 'MENU' }],
        [{ text: '🧺 Ver carrito', callback_data: 'CART' }]
      ];
      response.ui_type = 'ADDED';
      response.session.pantalla_actual = 'CARRITO';
    }
  }

} else if (action === 'CART') {

  response.session.pantalla_actual = 'CARRITO';

  if (!cart.length) {
    response.text = '🧺 Tu carrito está vacío.';
    response.keyboard = [[
      { text: '🛒 Ir al menú', callback_data: 'MENU' }
    ]];
    response.ui_type = 'SINGLE';
  } else {
    const lines = cart
      .map(x => `• ${x.cantidad} × ${x.nombre} = ${money(x.cantidad * x.precio)}`)
      .join('\n');

    response.text =
      `🧺 *Tu carrito*\n\n${lines}\n\n` +
      `*Total: ${money(total())}*`;

    response.keyboard = [
      [{ text: '✅ Confirmar pedido', callback_data: 'CONFIRM' }],
      [
        { text: '🗑 Vaciar', callback_data: 'CLEAR' },
        { text: '➕ Agregar', callback_data: 'MENU' }
      ]
    ];

    response.ui_type = 'CART';
  }

} else if (action === 'CLEAR') {

  cart = [];
  response.text = '🗑 Carrito vaciado.';
  response.keyboard = [[
    { text: '🛒 Nuevo pedido', callback_data: 'MENU' }
  ]];
  response.ui_type = 'SINGLE';
  response.session.pantalla_actual = 'CARRITO';

} else if (action === 'CONFIRM') {

  let ok = true;
  const lacks = [];

  for (const x of cart) {
    const p = menu.find(m => String(m.id_producto) === x.id);
    if (!p || Number(p.stock) < Number(x.cantidad)) {
      ok = false;
      lacks.push(x.nombre);
    }
  }

  if (!cart.length) {
    response.text = 'El carrito está vacío.';
    response.keyboard = [[
      { text: '🛒 Menú', callback_data: 'MENU' }
    ]];
    response.ui_type = 'SINGLE';

  } else if (!ok) {
    response.text = `⚠️ El stock cambió para: ${lacks.join(', ')}. Revisa el carrito.`;
    response.keyboard = [[
      { text: '🧺 Carrito', callback_data: 'CART' }
    ]];
    response.ui_type = 'SINGLE';

  } else {
    const now = new Date();
    const date = now.toLocaleDateString('en-CA', {timeZone:'America/Bogota'});
    const time = now.toLocaleTimeString('es-CO', {
      timeZone: 'America/Bogota',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });

    const suffix = String(now.getTime()).slice(-6);
    const orderId = `DB-${date.replaceAll('-', '')}-${suffix}`;
    const user = users.find(u => String(u.telegram_id) === evt.telegram_id) || {};

    response.order = {
      id_pedido: orderId,
      id_usuario: evt.telegram_id,
      detalles_pedido: JSON.stringify(cart),
      total_pago: total(),
      estado: 'Recibido',
      fecha: date,
      hora: time,
      departamento_oficina: user.departamento_oficina || 'POR DEFINIR',
      canal: 'Telegram',
      ultima_actualizacion: now.toISOString()
    };

    response.stock_updates = cart.map(x => {
      const p = menu.find(m => String(m.id_producto) === x.id);
      return {
        id_producto: x.id,
        stock: Number(p.stock) - Number(x.cantidad)
      };
    });

    response.text =
      `✅ *Pedido confirmado*\n\n` +
      `Orden: *${orderId}*\n` +
      `Total: *${money(total())}*\n` +
      `Estado: *Recibido*\n\n` +
      `Te avisaremos cuando cambie el estado.`;

    response.keyboard = [[
      { text: '📦 Ver estado', callback_data: 'STATUS' }
    ]];

    response.ui_type = 'SINGLE';
    cart = [];
    response.session.pantalla_actual = 'PEDIDO_CONFIRMADO';
  }

} else if (action === 'POINTS') {

  const user = users.find(u => String(u.telegram_id) === evt.telegram_id) || {};
  const nombre = user.nombre_completo || evt.nombre || 'Usuario';
  const puntos = Number(user.puntos_lealtad || 0);

  response.text =
    `Hola ${nombre}, actualmente tienes 🏆 ${puntos} puntos acumulados. ` +
    `¡Sigue comprando para canjear premios!`;

  response.keyboard = [[
    { text: '⬅️ Volver al menú principal', callback_data: 'HOME' }
  ]];

  response.ui_type = 'SINGLE';
  response.session.pantalla_actual = 'PUNTOS';

} else if (action === 'STATUS') {

  response.text =
    '📦 *Estado del pedido*\n\n' +
    'El módulo de seguimiento detallado se conecta con el workflow de cocina.';

  response.keyboard = [[
    { text: '⬅️ Volver al menú principal', callback_data: 'HOME' }
  ]];

  response.ui_type = 'SINGLE';
  response.session.pantalla_actual = 'ESTADO';

} else if (action === 'HISTORY') {

  response.text =
    '📜 *Historial de pedidos*\n\n' +
    'El historial detallado se habilita en la siguiente fase del workflow.';

  response.keyboard = [[
    { text: '⬅️ Volver al menú principal', callback_data: 'HOME' }
  ]];

  response.ui_type = 'SINGLE';
  response.session.pantalla_actual = 'HISTORIAL';

} else {

  home();
}

response.session.telegram_id = evt.telegram_id;
response.session.carrito_temporal = JSON.stringify(cart);
response.session.ultimo_cambio = new Date().toISOString();

return [{ json: response }];

const telegramId = String($('Motor Conversacional').first().json.order.id_usuario || '');

const usuario = $('Leer USUARIOS').all()
  .map(i => i.json)
  .find(u => String(u.telegram_id) === telegramId);

if (!usuario) {
  throw new Error(`No se encontró el usuario ${telegramId} en la hoja USUARIOS`);
}

return [{
  json: {
    telegram_id: telegramId,
    nombre_completo: usuario.nombre_completo || '',
    puntos_lealtad: Number(usuario.puntos_lealtad || 0)
  }
}];
